query read_through_cache {
 match "architecture.read-through-cache.read_fill"(read:$read,cache:$cache,key:$key,lookup:$lookup,load:$load,write:$write);
 require $unit HAS_METHOD $read;
 require $unit HAS_FIELD $cache;
 require $cache ASSIGNED_FROM $construction;
 require $construction ALLOCATES_TYPE $storage_type;
 require $unit HAS_METHOD $initialize;
 require $initialize HAS_CALL $construction;
 emit $unit,$read,$cache,$key,$lookup,$load,$write,$initialize,$construction,$storage_type;
}

